package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class PlanController {

    /** What the screen shows of a plan: its amount as text with two decimals, its dates, its interval
     *  or day of the month (the other null), and how many claims it has made so far. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated) {
        static PlanView of(Plan plan) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().setScale(2).toPlainString(),
                    plan.getStartDate(), plan.getEveryDays(), plan.getMonthDay(), plan.getEndDate(),
                    plan.getGenerated());
        }
    }

    /** The plan form: a required amount with up to two decimals, an optional start (the sheet's today
     *  when left out), either a whole number of days it repeats every or a day of the month it falls
     *  on (the other blank), and a required end. */
    public record PlanForm(@NotNull @Pattern(regexp = "\\s*\\d{1,12}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate start, @Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String every,
            @Pattern(regexp = "\\s*(\\d{1,2})?\\s*") String day, @NotNull LocalDate end) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        Integer everyValue() {
            return every == null || every.isBlank() ? null : Integer.valueOf(every.trim());
        }

        Integer dayValue() {
            return day == null || day.isBlank() ? null : Integer.valueOf(day.trim());
        }
    }

    /** How many claims a generate made. */
    public record Generated(int made) {
    }

    private final PlanService service;

    public PlanController(PlanService service) {
        this.service = service;
    }

    @GetMapping("/plans")
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(PlanView::of).toList();
    }

    @PostMapping("/people/{personId}/plans")
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PlanForm form) {
        return PlanView.of(service.add(sheetId.trim(), user.trim(), personId, form.amountValue(), form.start(),
                form.everyValue(), form.dayValue(), form.end()));
    }

    @PostMapping("/plans/generate")
    public Generated generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new Generated(service.generate(sheetId.trim(), user.trim()));
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person's plan: a draft claim of its amount on its start date and every so many days after, or
 *  on a day of every month from the start's month (a day beyond the month's length falling on its
 *  last day, dates before the start left out), up to its end date. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate startDate;

    /** The days it repeats every; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer everyDays;

    /** The day of the month a monthly plan falls on; null for one that repeats every so many days. */
    @Column(name = "month_day")
    private Integer monthDay;

    @Column(name = "end_date", nullable = false)
    private LocalDate endDate;

    /** The plan dates it has made its claim for. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_date", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "on_date", nullable = false)
    private Set<LocalDate> made = new HashSet<>();

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate startDate, Integer everyDays,
            Integer monthDay, LocalDate endDate) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.startDate = startDate;
        this.everyDays = everyDays;
        this.monthDay = monthDay;
        this.endDate = endDate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Make the plan another person's (the one it was for was merged into them). */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStartDate() {
        return startDate;
    }

    public Integer getEveryDays() {
        return everyDays;
    }

    public Integer getMonthDay() {
        return monthDay;
    }

    public LocalDate getEndDate() {
        return endDate;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }

    /** The plan dates up to its end and the day given, oldest first, that it has made no claim for. */
    public List<LocalDate> dueUpTo(LocalDate today) {
        LocalDate last = endDate.isBefore(today) ? endDate : today;
        List<LocalDate> due = new ArrayList<>();
        if (monthDay != null) {
            for (YearMonth m = YearMonth.from(startDate); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(monthDay, m.lengthOfMonth()));
                if (!d.isBefore(startDate) && !d.isAfter(last) && !made.contains(d)) {
                    due.add(d);
                }
            }
            return due;
        }
        for (LocalDate d = startDate; !d.isAfter(last); d = d.plusDays(everyDays)) {
            if (!made.contains(d)) {
                due.add(d);
            }
        }
        return due;
    }

    /** Note that the plan has made its claim for the date. */
    public void markMade(LocalDate date) {
        made.add(date);
    }
}
