package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/** The plans people on a sheet have, and the draft claims they make. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final TransactionTemplate transaction;
    private final Audit audit;

    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims, SheetService sheets,
            PlatformTransactionManager transactions, Audit audit) {
        this.plans = plans;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.transaction = new TransactionTemplate(transactions);
        this.audit = audit;
    }

    /** The plans on the sheet in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a plan for a person, repeating either every so many days or monthly on a day of the month;
     *  a start left out takes the sheet's today. Refused for an amount that is not above zero, neither
     *  or both of an interval and a day, an interval below one day, a day outside 1 to 31, and an end
     *  before the start. */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (amount.signum() <= 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's amount must be above zero");
        }
        if ((every == null) == (day == null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A plan repeats either every so many days or on a day of the month");
        }
        if (day != null && (day < 1 || day > 31)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's day of the month is 1 to 31");
        }
        if (every != null && every < 1) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan repeats every one day or more");
        }
        LocalDate from = start != null ? start : sheets.today(sheetId);
        if (end.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan cannot end before it starts");
        }
        Plan saved = plans.saveAndFlush(new Plan(sheetId, person.getId(), amount, from, every, day, end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + amount.setScale(2).toPlainString() + " start=" + from
                + (day != null ? " day=" + day : " every=" + every) + " end=" + end);
        return saved;
    }

    /** Make, for every plan on the sheet in the order they were added, a draft claim of its amount
     *  with an empty note for each of its dates up to its end and the sheet's today that has none
     *  yet, oldest first. Each claim is added as the claim form adds it, in a transaction of its
     *  own: a date the form refuses is skipped, and tried again by the next generate. Returns how
     *  many claims were made. */
    public int generate(String sheetId, String user) {
        LocalDate today = sheets.today(sheetId);
        int made = 0;
        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheetId)) {
            for (LocalDate date : plan.dueUpTo(today)) {
                try {
                    transaction.executeWithoutResult(status -> {
                        Plan locked = plans.findById(plan.getId()).orElseThrow();
                        if (!locked.dueUpTo(date).contains(date)) {
                            return;
                        }
                        claims.add(sheetId, user, locked.getPersonId(), locked.getAmount(), date, "");
                        locked.markMade(date);
                        plans.saveAndFlush(locked);
                    });
                    made++;
                } catch (ResponseStatusException refused) {
                    // the claim form refused the date: it is tried again next time
                }
            }
        }
        return made;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A person's plan: a draft claim of its amount on its start and every so many days after, or
 *  monthly on a day of the month (the other null), up to its end; with how many claims it has made
 *  so far. */
export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
}

/** The plan form as typed: a blank start takes the sheet's today. */
export interface PlanFields {
  amount: string;
  start: string;
  every: string;
  day: string;
  end: string;
}

// The plans of the people on the active sheet, and the generate that makes their claims.
@Injectable({ providedIn: 'root' })
export class Plans {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The plans on the sheet in the order they were added. */
  list(sheetId: string): Promise<Plan[]> {
    return firstValueFrom(this.http.get<Plan[]>(`/api/sheets/${encodeURIComponent(sheetId)}/plans`));
  }

  /** Add a plan for the person; refused for a bad amount, interval or day, or an end before the start. */
  add(personId: number, f: PlanFields): Promise<Plan> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<Plan>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/plans`,
        { amount: f.amount, start: f.start || null, every: f.every || null, day: f.day || null, end: f.end || null },
        { headers: { 'X-User': user } }),
    );
  }

  /** Make the claims every plan on the sheet is due: how many were made. */
  generate(): Promise<{ made: number }> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<{ made: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/plans/generate`, null,
        { headers: { 'X-User': user } }),
    );
  }

  private active(): { sheetId: string; user: string } {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return { sheetId, user };
  }
}
import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Plan, Plans } from '../../core/plans';

// A person's plans (every so many days or monthly on a day), in the order they were added, each with how many claims it has made so far;
// and the form that adds one.
@Component({
  selector: 'app-person-plans',
  imports: [ReactiveFormsModule],
  template: `
    <ul aria-label="Plans">
      @for (pl of plans(); track pl.id) {
        <li [attr.data-testid]="'plan-row-' + pl.id">
          <span data-testid="plan-amount-shown">{{ pl.amount }}</span>
          from <span data-testid="plan-start">{{ pl.start }}</span>
          @if (pl.day !== null) {
            monthly on day <span data-testid="plan-day">{{ pl.day }}</span>
          } @else {
            every <span data-testid="plan-every">{{ pl.every }}</span> days
          }
          to <span data-testid="plan-end">{{ pl.end }}</span>;
          made <span data-testid="plan-generated">{{ pl.generated }}</span>
        </li>
      }
    </ul>
    <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="'Add a plan of ' + name()">
      <label [for]="'plan-form-amount-' + personId()">Plan amount</label>
      <input [id]="'plan-form-amount-' + personId()" inputmode="decimal" data-testid="plan-form-amount"
        formControlName="amount" />
      <label [for]="'plan-form-start-' + personId()">Start</label>
      <input [id]="'plan-form-start-' + personId()" type="date" data-testid="plan-form-start" formControlName="start" />
      <label [for]="'plan-form-every-' + personId()">Every (days)</label>
      <input [id]="'plan-form-every-' + personId()" inputmode="numeric" data-testid="plan-form-every"
        formControlName="every" />
      <label [for]="'plan-form-day-' + personId()">Or monthly on day (1 to 31)</label>
      <input [id]="'plan-form-day-' + personId()" inputmode="numeric" data-testid="plan-form-day"
        formControlName="day" />
      <label [for]="'plan-form-end-' + personId()">End</label>
      <input [id]="'plan-form-end-' + personId()" type="date" data-testid="plan-form-end" formControlName="end" />
      <button type="submit" data-testid="plan-form-submit">Add plan</button>
      @if (error()) {
        <p role="alert" data-testid="plan-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class PersonPlans {
  private readonly api = inject(Plans);

  readonly personId = input.required<number>();
  readonly name = input.required<string>();
  readonly plans = input.required<Plan[]>();
  readonly added = output<Plan>();

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    start: new FormControl('', { nonNullable: true }),
    every: new FormControl('', { nonNullable: true }),
    day: new FormControl('', { nonNullable: true }),
    end: new FormControl('', { nonNullable: true }),
  });
  protected readonly error = signal('');
  /** Whether an add is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const f = this.form.getRawValue();
    const amount = f.amount.trim();
    const every = f.every.trim();
    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount) || Number(amount) <= 0) {
      this.error.set('Enter an amount above zero with up to two decimals.');
      return;
    }
    const day = f.day.trim();
    if (!every === !day) {
      this.error.set('Enter either a number of days or a day of the month.');
      return;
    }
    if (every && (!/^\d{1,5}$/.test(every) || Number(every) < 1)) {
      this.error.set('Enter a whole number of days, at least 1.');
      return;
    }
    if (day && (!/^\d{1,2}$/.test(day) || Number(day) < 1 || Number(day) > 31)) {
      this.error.set('Enter a day of the month from 1 to 31.');
      return;
    }
    if (!f.end) {
      this.error.set('Enter the day the plan ends.');
      return;
    }
    if (f.start && f.end < f.start) {
      this.error.set('The end cannot be before the start.');
      return;
    }
    this.submitting = true;
    try {
      this.added.emit(await this.api.add(this.personId(), { amount, start: f.start, every, day, end: f.end }));
    } catch {
      this.error.set('The plan could not be added.');
    } finally {
      this.submitting = false;
    }
  }
}

